/**
 * Attention UI for a RUNNING Koncha tab only. No chat plaintext, peer names or
 * room IDs enter the system notification, title, favicon, or app badge.
 * Does not implement Push API/background delivery.
 */
export function badgeText(count) {
  if (!Number.isFinite(count) || count <= 0) return '';
  return count > 99 ? '99+' : String(Math.floor(count));
}

export function badgeFavicon(count, bright = true) {
  const num = badgeText(count);
  // All dynamic content is a numeral generated by badgeText, never chat text.
  const accent = bright ? '#d95b49' : '#b44d41';
  const labelSize = num.length > 2 ? 11 : 14;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">
    <rect x="1" y="1" width="62" height="62" rx="13" fill="#29453e"/>
    <path d="M16 25h19v6H16zm0 12h19v6H16z" fill="#e4eee7"/>
    <circle cx="47" cy="17" r="16" fill="${accent}" stroke="#29453e" stroke-width="2"/>
    <text x="47" y="22" fill="#fff" font-family="system-ui,sans-serif" font-size="${labelSize}" font-weight="700" text-anchor="middle">${num}</text>
  </svg>`;
}

export class AttentionController {
  constructor({ doc = globalThis.document, nav = globalThis.navigator, win = globalThis.window, labels = () => ({}) } = {}) {
    this.doc = doc; this.nav = nav; this.win = win; this.labels = labels;
    this.count = 0; this.soundEnabled = true; this.audio = null; this.blink = null;
    this.title = doc.title;
    this.favicon = doc.querySelector('link[rel="icon"]');
    this.originalIcon = this.favicon?.getAttribute('href') || '/icon.svg';
    this.visibilityChanged = () => { if (!this.doc.hidden) this.clear(); };
    doc.addEventListener('visibilitychange', this.visibilityChanged);
    this.registrationPromise = null;
  }

  setSound(enabled) { this.soundEnabled = !!enabled; }

  // Called only in user gestures: audio autoplay policy may prevent use otherwise.
  unlockAudio() {
    if (!this.soundEnabled) return;
    try {
      const Audio = this.win.AudioContext || this.win.webkitAudioContext;
      if (!Audio) return;
      if (!this.audio) this.audio = new Audio();
      if (this.audio.state === 'suspended') void this.audio.resume().catch(() => {});
    } catch { /* Audio unsupported, other visual alerts still work. */ }
  }

  chime() {
    const context = this.audio;
    if (!this.soundEnabled || !context || context.state !== 'running') return;
    try {
      const start = context.currentTime;
      for (const [offset, pitch] of [[0, 740], [0.12, 960]]) {
        const tone = context.createOscillator();
        const gain = context.createGain();
        tone.type = 'sine'; tone.frequency.value = pitch;
        gain.gain.setValueAtTime(0.0001, start + offset);
        gain.gain.exponentialRampToValueAtTime(0.045, start + offset + 0.015);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + offset + 0.14);
        tone.connect(gain); gain.connect(context.destination);
        tone.start(start + offset); tone.stop(start + offset + 0.15);
      }
    } catch { /* Sound is best-effort. */ }
  }

  incoming(amount) {
    if (!this.doc.hidden || amount <= 0) return;
    this.count = Math.min(999, this.count + Math.floor(amount));
    this.render();
    this.chime();
    void this.showSystemNotification();
  }

  render() {
    if (!this.doc.hidden || this.count === 0) return;
    const text = badgeText(this.count);
    this.doc.title = `(${text}) ${this.title}`;
    this.updateIcon(true);
    if (!this.blink) {
      let highlighted = true;
      this.blink = this.win.setInterval(() => {
        if (!this.doc.hidden || !this.count) return;
        highlighted = !highlighted;
        this.updateIcon(highlighted);
      }, 1400);
    }
    if (typeof this.nav.setAppBadge === 'function') {
      try { void Promise.resolve(this.nav.setAppBadge(this.count)).catch(() => {}); } catch { /* unsupported */ }
    }
  }

  updateIcon(bright) {
    if (this.favicon) this.favicon.setAttribute('href', `data:image/svg+xml,${encodeURIComponent(badgeFavicon(this.count, bright))}`);
  }

  clear() {
    this.count = 0;
    this.doc.title = this.title;
    if (this.blink) this.win.clearInterval(this.blink);
    this.blink = null;
    if (this.favicon) this.favicon.setAttribute('href', this.originalIcon);
    if (typeof this.nav.clearAppBadge === 'function') {
      try { void Promise.resolve(this.nav.clearAppBadge()).catch(() => {}); } catch { /* unsupported */ }
    }
  }

  async ensureWorker() {
    if (!this.nav.serviceWorker) throw new Error('service_worker_unavailable');
    if (!this.registrationPromise) {
      this.registrationPromise = this.nav.serviceWorker.register('/sw.js', { scope: '/' }).catch(error => {
        this.registrationPromise = null;
        throw error;
      });
    }
    return this.registrationPromise;
  }

  // MUST be called synchronously from a click/tap handler (before await).
  async requestPermission() {
    const Notifications = this.win.Notification;
    if (!this.win.isSecureContext || !Notifications?.requestPermission) return 'unavailable';
    const result = Notifications.permission === 'default'
      ? await Notifications.requestPermission()
      : Notifications.permission;
    if (result === 'granted') {
      try { await this.ensureWorker(); } catch { return 'unavailable'; }
    }
    return result;
  }

  async showSystemNotification() {
    const Notifications = this.win.Notification;
    if (!Notifications || Notifications.permission !== 'granted' || !this.win.isSecureContext) return;
    try {
      const sw = await this.ensureWorker();
      const words = this.labels();
      await sw.showNotification(words.title || 'Koncha', {
        body: words.body || 'You have a new message. Open Koncha to read it.',
        tag: 'koncha-unread', icon: '/icon-192.png', badge: '/icon-192.png',
        renotify: false, data: { url: '/?resume=1' }
      });
    } catch { /* No alert leakage to a third-party fallback. */ }
  }
}
